/* Semantica Renderer — minimal reset so the bound HTML controls its own layout.
 * Power BI wraps the visual in a container; this file just ensures our root
 * element fills it and passes pointer events through to the inner HTML.
 */

.visual {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
  position: relative;
  font-family: 'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.visual * {
  box-sizing: border-box;
}
